INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаррароти: муҳимии зиёд кардани самаранокии сабзавот партиявӣ (stripe irrigation)</h2>\n<p>Дарёфъаи заҳролҳои кишоварӣ ва афзоиши хароҷоти истеҳсол кишоваронро маҷбур кардааст, ки усулҳое ҷӯянд, ки ҳамзамон истеъмоли обро коҳиш медиҳад ва ҳосилро дар ҳектар то босафард меоварад. Дар ин миён, <strong>оғозии партиявӣ (stripe irrigation)</strong> ба ҳисоби яке аз самараноки тарҳҳои намоишии ғулбӣ (drip) таваҷҷӯҳи махсус ҷалб кардааст. Ин усул бо таъмири мустақими решаҳои растанӣ аз партияи намдор, боиси афзоиши наздик ҳосили ниҳоии меҳва мешавад.</p>\n<p>Баръакси намоиши бароишӣ, ки боиси шӯрзоршавии сатҳӣ ва аз даст рафтани об аз роҳи таҳҷиҳот (evaporation) мешавад, партиявӣ (stripe irrigation) бо ба вуҷуд овардани як канали тарқе ва амиқ дар зери сатҳи хок, дастрасии решаҳои асосии меҳвараҳоро ба намдорӣ ва моддаҳои ғизоӣ кафолат мекунад. Саҳеб аз ин мақола, муҳокамаи дақиқи омилҳои таъсиррасон ба <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b4%d8%a8%d8%af%d8%b1-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">миқдори ҳосили ҷӯлаҳо дар ҳектар: омилҳои таъсиррасон ва роҳҳои афзоиш</a> (масалан монанд дар парвариши сабзавот) ва мутобиқ шудани он бо шароити меҳварон, то кишоварон бо дониши техникӣ қарорҳои беҳтарро гирад.</p>\n\n\n\n<h2>Асосҳои фаъолияти партиявӣ (stripe irrigation) ва таъсири он ба решаҳои меҳварон</h2>\n<h3>Механизми ҷудокунии намнокӣ дар решаҳо</h3>\n<p>Порек як наботати кам-реша, вале вобаста ба намнокии сатҳӣ ва миёна аст. Системаи нақббандии чаркоӣ, баъд аз нақббандиҳои васеъ, амиқрозии намнокӣро беҳтар мекунанд. Бо истифода аз тамғаҳои хурд, ки бо суръати паст барорида мешаванд, намнокӣ ба таври якҷоя дар амиқии 10 то 20 сантиметрӣ ҷудо мешавад. Ин амиқӣ айнан дар минтақаи фаъолияти асосии решаҳои порек ҷойгир аст.</p>\n<p>Барои фаҳмиши беҳтар, ба <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%da%af%d8%b1%d9%87%d8%a7%db%8c-%db%8c%d8%a7-%d8%ae%d9%86%d8%af%d9%82/">оборӣ кардани канавҳо</a> диққат диҳед, ки онҳо механизми монанд доранд, аммо нақббандии чаркоии муосир дақиқии баландтро дар идоракунии шикофарӣ дорад. Ин дақиқӣ аз камоборӣ ё гарғаршавии решаҳо пешгиравӣ мекунад ва ҷудокунии оксиген ба решаҳо беҳтар мешавад. Дар шартҳое, ки нақббандии чаркоӣ дуруст насб шавад, сатҳи намнокӣ комилан нигоҳ дошта мешавад ва наботати порек стресси камтарро таҷриба мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-تره-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت تره در هکتار با نوار تیپ - تصویر 1"/><figcaption>crop yield per hectare drip irrigation порек</figcaption></figure>\n<h3>Таъсир бар ҷазби моддаҳои ғизоӣ</h3>\n<p>Яке аз бартарии асосии нақббандии чаркоӣ, имконияти ғизои зеризаминӣ (Fertigation) аст. Дар парвариши порек, ки ба фосфор ва калций ҳассос аст, ҷойгиркунии муқоди чӯмраҳои ҳалӣ дар роҳи нақббандии чаркоӣ ҷазби ин моддаҳоро ба таври назаррас баланд мекунад. Баъд аз усулҳои қадимӣ, ки моддаҳои чӯмраӣ дар сатҳ паҳн мешаванд, дар ин усул ғизои моддаҳои чӯмраӣ то 30% зиёд мешавад ва дар натиҷа, миёнаи вазни сари порек дар ҳар гектар баландтар мешавад.</p>\n\n<h2>Омилҳои муайянкунандаи ҳосили сабзӯсабзӣ дар ҳектар</h2>\n<h3>Фосилагузорӣ дар наъмунишӣ ва ҷойгиршавии риштаҳо</h3>\n<p>Давомият ва фосилаи риштаҳо аз якдигар аммоли асосии муайянкунандаи сатҳи зер кӯфтор мебошад. Одатан барои сабзӣ фосилаи байни риштаҳо 60 то 80 сантиметр тавсия мешавад. Агар фосила камтар бошад, намии риштаҳо бо ҳам омехта шуда боиси рушди обшавии баргҳо мегардад, вале агар бисёр зиёд бошад, ҷушҳои хушк пайдо шуда рушди растаниҳо боздошта мешавад. Дар <a href="https://navar-abyari.ir/bell-pepper-yield-per-hectare-iraq-farmers-guide/">bell pepper yield per hectare iraq farmers guide</a> чунин ҳолат низ ба мукаммалкунӣ (оптимизатсия) кардани фосилагузории риштаҳо барои гиёҳони баргдор ишора шудааст, ки барои сабзӣ низ ҳаром аст.</p>\n<h3>Навъи хок ва гушқидиҳии он</h3>\n<p>Дар ҳоки равған, риштаи тасимӣ бояд бо шиддати баландтар кор кунад, то ки паҳншавии амуди намӣ кофӣ бошад. Дар ҳоки чангӣ, суръати хориш кардан бояд бисёр паст бошад, то аз гилсоракорӣ ва камبودии оксиген пешгирӣ карда шавад. Кишоткор бояд пеш аз насб кардан таҷрибаи гушқидиҳиро иҷро кунад. Намои рафти шиддати ришта бо намуди хок, аммоли асосии камшавии миқдори заъфарон (ва монанди дигар гиёҳҳои паҳншуда) дар ҳектар хоҳад буд, зеро растанӣ бо паридани хок ва шӯрокории хок муқобила мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-تره-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت تره در هکتار با نوار تیپ - تصویر 2"/><figcaption>ҳосили зирعي дар ҳектар оробии тағҷимӣ сабзӣ</figcaption></figure>\n\n\n\n<h2>Нуқтаҳои амалӣ барои ҳосилоти бартарӣ ҷустан</h2>\n<h3>Барномаи таймукунии обориш</h3>\n<ol>\n<li><strong>Давраи омодагӣ:</strong> 3 то 5 рӯз пеш аз нуҳуф, обориши чуқур бо рафси нимабанд баъд аз боришот анҷом дода шавад, то намӣ барои намаиш кардани донҳо кофӣ бошад.</li>\n<li><strong>Давраи рушд:</strong> Оборишҳои такрорӣ (ҳар 2 то 3 рӯз) бо сарпиҷояш паст (2 то 3 литр дар соат) тавсия дода мешавад. Таре ба намаши доимӣ ҳассос аст ва қатъшавии намӣ боиси сахт шудани сағаҳо мегардад.</li>\n<li><strong>Давраи ҷамъбарӣ:</strong> 48 соат пеш аз ғолуби ахирин, обориш қатъ карда шавад, то намии сатҳӣ кам гардад ва нигоҳдории таре дар анбор осонтар шавад.</li>\n</ol>\n<h3>Кориб додани зарари занбӯрҳо ва идоракунии намӣ</h3>\n<p>Рطубати баланди дар минтақаи намуи рибонӣ метавонад имконияти сироят ба бемориҳои занболаи баргҳоро зиёд кунад, агар намии сатҳ назорат нашавад. Маслиҳат дода мешавад, ки аз пӯши пластики рӯйи намуи рибонӣ истифода баред, то аз бухоршавӣ ва афзоиши дарахтони зарарзан бозгашт карда шавад. Дар бораи <a href="https://navar-abyari.ir/kammiyat-buthour-al-kanwala-fi-al-hahtar/">kammiyat buthour al kanwala fi al hahtar</a> (миқдори ҳосили кунҷут дар гектар) низ принсипҳои мушаххас барои идоракунии намӣ ва коҳиши беморӣ татбиқ карда мешаванд. Истифодаи системаи шустушӯи наму бо маҳлулҳои кислотӣ ё ишқалӣ барои пешгирии ҷамъшавии отрезҳо умри муҳлати истифодаи таҷҳизотро зиёд мекунад.</p>\n<h3>Назорати фишор ва рафти об</h3>\n<p>Фишори доимии 1 атмосфера беҳтарин фишор барои намуҳои рибони стандартист. Паст шудани фишор дар охирҳои хат метавонад ба хушк будани ҷузъҳои охир баромад. Насб кардани регулятори фишор дар оғози замин зарур аст. Инчунин, ҳар 10 то 15 рӯз як бор як қисм аз наморо кушода, отрезҳоро бо оқаи тезшӯй об равона кунед ва хориҷ кунед.</p>\n\n<h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2>\n<h3>1. Оё намуи рибонӣ танҳо барои заминҳои ҳамвор мувофиқ аст?</h3>\n<p>Намуи рибонӣ аз рӯи моҳият барои заминҳои ҳамвор тарҳрезӣ шудааст, аммо бо истифода аз ғазакҳои мувозинати фишор ва ҳисобкунии шабҳарорӣ, метавон онро дар заминҳои бо шабҳарории то 10% низ истифода бард. Дар заминҳои хеле шабҳароршуда, ба ҷои намуи рибонӣ, аз қатрагониҳои ҷой истифода мебаранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-تره-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت تره در هکتار با نوار تیپ - تصویر 3"/><figcaption>crop yield per hectare drip irrigation тр</figcaption></figure>\n<h3>2. Чӣ тавр шумо хушкшавии парролҳои оброӣ (strip) дар картофро муайян мекунед?</h3>\n<p>Хушкшавии парролҳои оброӣ бо хушкӣи сахти канорҳои байни парролҳо ва тағйирёбии ранги хок аз хокистарӣ ба сафед муайян мешавад. Дар картофа, ишораи хушкшавии парролҳо, нуқри дурдонаҳои нав ва сахт шудани сари картофа мебошад. Кам шудани сарфи об ва зиёд шудани вақти обёрӣ барои ҷазби амудии намӣ масъалаҳоро ҳал мекунад.</p>\n<h3>3. Фарқи парроли таипӣ аз парроли чекирӣ дар нарх аст?</h3>\n<p>Парроли таипӣ ба сабаби сохтори қуттии мустаҳкам ва муқовимат ба фишор, давоми қобилияти кор кардани баландтар дорад ва камтар ниёз ба ивазкунӣ дорад. Дар айни замон, парролҳои чекирӣ одатан сабуктар ва арзонтаранд, аммо агар аз рӯяшон аз ҷониби одамон ё механизмҳо гузаранд, вайрон мешаванд. Барои боғҳои картофа, ки кӯчат ва камҳорӣ доранд, парроли таипӣ бо пӯшишкунандагии шустанӣ (flushable) имконоти давомнокии бештарро таъмин мекунад.</p>\n\n\n\n<h2>Хулоса: Ояндаи парвариши картофа бо обёрии муосир</h2>\n<p>Истифодаи <strong>парроли таипӣ</strong> дар парвариши картофа, ҳамоҳангӣ таъҷилонӣ барои кам кардани истифодаи об ва зиёд кардани самаранокиятро ба вуҷуд меорад. Бо риоя кардани принсипҳои андозакунӣ (layout), идоракунии сарфи об ва тозакунии муқаррарӣ, имкон дорад, ки ба зиёд шудани 20 то 35-фолии ҳосили картофа дар гектар ноил шудан мумкин аст. Деҳқононе, ки ба <a href="https://navar-abyari.ir/mazaya-sharit-al-ray/">Чӣ тавр дарозии умри кории рибери қатрагӣро зиёд кунед</a> (Роҳҳои зиёд кардани умри системаи рибери қатрагӣ) диққат диҳанд, дар дарозмуддат иҷозатҳои иқтисодии беҳтар дошта мешаванд. Ин усул на танҳо сифати сабзавотҳоро тавассути кам кардани бемориҳо нигоҳ медорад, балки коркарди зериҳиро барои ғалтгирии механизатсияшуда осонтар мекунад. Сарфавтиро ба системаи мувофиқи рибери қатрагӣ анҷом додан қадам сабз ба самти кишоварзии устувор аст.</p>','Миқдори ҳосилнокии тухмдори туба барои ҳар як гектар бо системаи наморанди нахустин','Ошноӣ бо муфассотҳои техникӣ ва амалӣ барои зиёд кардани ҳосили шӯрпоя дар як гектар бо истифода аз оборӣ аз рӯйхат (лента). Таҳлили омили таъсирбахш ба ҳосилнокии решаҳои бардошт ва муаррифӣ чораҳои беҳтар кардани истифодаи об.','publish','closed','closed','mishori-hosilnoki-tuhm-dori-tuba',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
